def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    height, width = r1 - r0 - 1, c1 - c0 - 1
    layers = min(height, width) // 2
    colors = [2, 5]
    for d in range(2, layers):
        colors.append(colors[layers - 1 - d] if layers - 1 - d >= 0 else 0)
    # Symmetric layers from outside in: 2, 5, ... center ... 5, 2.
    seq = [2, 5] + [0] * max(0, layers - 4) + [5, 2]
    if layers == 1:
        seq = [2]
    elif layers == 2:
        seq = [2, 5]
    elif layers == 3:
        seq = [2, 5, 0]
    elif layers == 4:
        seq = [2, 5, 5, 2]
    else:
        seq = [2, 5] + [0] * (layers - 4) + [5, 2]

    for d, color in enumerate(seq, 1):
        top, bottom = r0 + d, r1 - d
        left, right = c0 + d, c1 - d
        for c in range(left, right + 1):
            out[top][c] = out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = out[r][right] = color
    return out
